// Generated by vibelang from src/outbox.vibe; the migrate flow writes it again with each batch.
import * as Option from "effect/Option";
import { Context, Effect } from "effect";
// The device has one durable outbox (decision 0002 §3), which chat's store builds and leads
// (src/features/chat/store.ts). A feature that writes through it hands its writes over here, from a layer built below
// chat's store: the collections its writes' optimistic rows go in and the mutations that send them, each under a name
// that never changes, because a stored write names its collection and its mutation by them. Each mutation has its
// services already: it runs as the outbox sends it, in whichever tab leads.
/** The writes features send through the device's outbox besides chat's own questions. */
export class OutboxWrites extends Context.Service()("@smthrs/mvp/OutboxWrites") {
    /**
     * `writes` added to the writes a layer below handed over, if any: how a second feature hands its writes to the same
     * outbox. Its names must be new: the earlier feature's stay as they were.
     */
    static adding = (writes) => Effect.map(Effect.serviceOption(OutboxWrites), (below) => {
        const earlier = Option.getOrElse(below, () => ({ collections: {}, mutations: {}, parked: {} }));
        return OutboxWrites.of({
            collections: { ...writes.collections, ...earlier.collections },
            mutations: { ...writes.mutations, ...earlier.mutations },
            parked: { ...writes.parked, ...earlier.parked },
        });
    });
}
